          accessories?: string; // Jewelry, weapons, bags, distinctive items (e.g., "silver pendant, sword at hip")
          distinguishing?: string; // Scars, tattoos, birthmarks if any (e.g., "scar across left cheek")
        }; // Complete visual ap

